using System;
using System.Diagnostics;

public class Program
{
    public static void Main()
    {
        // PROGRAM: Membandingkan Alokasi Memori: Substring vs ReadOnlySpan
        string rawHeader = "Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.dummyPayload";
        const int Iterations = 500_000;

        // 1. Cara Lama: string.Substring (Memicu Ratusan Ribu Objek Heap)
        GC.Collect();
        long memBefore1 = GC.GetTotalMemory(true);
        var sw1 = Stopwatch.StartNew();

        for (int i = 0; i < Iterations; i++)
        {
            string token = rawHeader.Substring(21); // Alokasi string baru setiap iterasi!
        }
        sw1.Stop();
        long memAfter1 = GC.GetTotalMemory(false);
        Console.WriteLine($"[Substring] Waktu: {sw1.ElapsedMilliseconds} ms | Alokasi Heap: {(memAfter1 - memBefore1) / (1024 * 1024)} MB");

        // 2. Cara Modern: ReadOnlySpan.Slice (Zero Allocation)
        GC.Collect();
        long memBefore2 = GC.GetTotalMemory(true);
        var sw2 = Stopwatch.StartNew();

        ReadOnlySpan<char> headerSpan = rawHeader.AsSpan();
        for (int i = 0; i < Iterations; i++)
        {
            ReadOnlySpan<char> tokenSpan = headerSpan.Slice(21); // ZERO ALOKASI HEAP!
        }
        sw2.Stop();
        long memAfter2 = GC.GetTotalMemory(false);
        Console.WriteLine($"[Span Slicing] Waktu: {sw2.ElapsedMilliseconds} ms | Alokasi Heap: {(memAfter2 - memBefore2) / (1024 * 1024)} MB (0 MB!)");
    }
}

