using System;

public class FastHeaderParser
{
    public static bool TryExtractBearerToken(string? authHeader, out string token)
    {
        token = "";
        if (string.IsNullOrWhiteSpace(authHeader)) return false;

        ReadOnlySpan<char> span = authHeader.AsSpan().Trim();
        const string prefix = "Bearer ";

        if (!span.StartsWith(prefix.AsSpan(), StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        ReadOnlySpan<char> tokenSlice = span.Slice(prefix.Length).Trim();
        if (tokenSlice.IsEmpty)
        {
            return false;
        }

        token = tokenSlice.ToString();
        return true;
    }

    public static void Main()
    {
        if (TryExtractBearerToken("Bearer abc123xyz", out string tok))
        {
            Console.WriteLine($"Token: {tok}");
        }
    }
}
